INSERT INTO "stock" VALUES(102,'UF89','4',1,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(103,'PC88','4',3,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(104,'UCL83','4',1,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(105,'UCH42','4',1,NULL,NULL,'2026-08-09',NULL);
