INSERT INTO "stock" VALUES(129,'10F1','5',2,NULL,NULL,'2026-08-09','early all glass screened amplifier pentode. The high impedance suggests applications with tuned circuits as anode loads, such as RF, or more likely due to the high gain, IF amplification in superhet radio, television or radar receivers.');
INSERT INTO "stock" VALUES(130,'30FL1','5',1,NULL,NULL,'2026-08-09','The triode, low power beam tetrode was designed as a general purpose valve.');
INSERT INTO "stock" VALUES(131,'30FL14','5',1,NULL,NULL,'2026-08-09','The 30FL14 triode pentode offers high voltage gain in a screened design. It was probably designed for VHF television use');
INSERT INTO "stock" VALUES(132,'30FL2','5',1,NULL,NULL,'2026-08-09','The triode, low power beam tetrode was designed as line time base and sync separator.');
INSERT INTO "stock" VALUES(133,'6BW7','5',1,NULL,NULL,'2026-08-09','The 6BW7 is an internally screened pentode.');
INSERT INTO "stock" VALUES(134,'6F28','5',1,NULL,NULL,'2026-08-09','The 6F28 is an amplifier beam tetrode of high mutual conductance');
INSERT INTO "stock" VALUES(135,'6F30','5',1,NULL,NULL,'2026-08-09','high gain VHF pentode. The mutual conductance is 15.6.');
INSERT INTO "stock" VALUES(136,'CV4014','5',2,NULL,NULL,'2026-08-09','The CV4014 is a UK service designation for the civilian M8083 or 6064, this in turn is a special quality version of the EF91 CV138. The M8083 has a more rugged build than the EF91 and was designed for operation in areas of vibration especially aircraft.');
INSERT INTO "stock" VALUES(137,'D77','5',1,NULL,NULL,'2026-08-09','The D77 is the Marconi equivalent of the Mullard EB91, and consists of two separate signal diodes in the envelope');
INSERT INTO "stock" VALUES(138,'DY87','5',2,NULL,NULL,'2026-08-09','television EHT rectifier introduced in 1956');
INSERT INTO "stock" VALUES(139,'EB91','5',2,NULL,NULL,'2026-08-09','double signal diode.');
INSERT INTO "stock" VALUES(140,'ECF805','5',2,NULL,NULL,'2026-08-09','Triode-Pentode   RF/IF-Stage   Controlling (mu)');
INSERT INTO "stock" VALUES(141,'ECL80','5',1,NULL,NULL,'2026-08-09','The ECL80 is a triode, output pentode for audio use.');
INSERT INTO "stock" VALUES(142,'EF183','5',4,NULL,NULL,'2026-08-09','The EF183 is a high gain variable μ RF amplifier pentod');
INSERT INTO "stock" VALUES(143,'EF184','5',8,NULL,NULL,'2026-08-09','purpose designed high gain frame grid pentode.');
INSERT INTO "stock" VALUES(144,'EF80','5',16,NULL,NULL,'2026-08-09','nternally screened pentode was a workhorse of the VHF TV');
INSERT INTO "stock" VALUES(145,'EF85','5',1,NULL,NULL,'2026-08-09','The EF85 is a VHF variable μ pentode and is the counterpart to the EF80 straight RF pentode');
INSERT INTO "stock" VALUES(146,'EY86','5',1,NULL,NULL,'2026-08-09','elevision EHT rectifier is rated in terms of peak inverse volts (PIV) and that is quoted at 22,000 Volts');
INSERT INTO "stock" VALUES(147,'PC900','5',3,NULL,NULL,'2026-08-09','The PC900 is a miniature VHF amplifier triode for use as an RF amplifier in television receivers. It is low impedance and has a high mutual conductance.');
INSERT INTO "stock" VALUES(148,'PC97','5',2,NULL,NULL,'2026-08-09','The PC97 is a VHF triode. It has a high mutual conductance and could be used as a signal pre-amplifier.');
INSERT INTO "stock" VALUES(149,'PCF210','5',1,NULL,NULL,'2026-08-09','No information');
INSERT INTO "stock" VALUES(150,'PCF80','5',7,NULL,NULL,'2026-08-09','triode pentode, with separate cathodes, designed to function as a mixer and oscillator in the tune');
INSERT INTO "stock" VALUES(151,'PCF802','5',3,NULL,NULL,'2026-08-09','rst stages in television line frequency generation prior to the line output stage. The pentode is described by Mullard as the oscillator while the triode is for service as a reactance valve');
INSERT INTO "stock" VALUES(152,'PCF805','5',2,NULL,NULL,'2026-08-09','oscillator and mixer for frequency changer use in VHF television receivers.');
INSERT INTO "stock" VALUES(153,'PCF806','5',1,NULL,NULL,'2026-08-09','triode and frame-grid pentode frequency changer for VHF television receivers up to 220 MHz');
INSERT INTO "stock" VALUES(154,'PCF905','5',1,NULL,NULL,'2026-08-09','No information, maybe PCF805 t is a purpose designed oscillator and mixer for frequency changer use in VHF television receivers.');
INSERT INTO "stock" VALUES(155,'PCH84','5',1,NULL,NULL,'2026-08-09','The PCF84 is triode pentode oscillator and mixer for the front ends of VHF television sets.');
INSERT INTO "stock" VALUES(156,'PCL805','5',1,NULL,NULL,'2026-08-09','triode pentode was purpose designed as a domestic television receiver frame output sta');
INSERT INTO "stock" VALUES(157,'PCL82','5',2,NULL,NULL,'2026-08-09','The PCL82 triode pentode is typical of valve television receivers audio output stages');
INSERT INTO "stock" VALUES(158,'PCL84','5',1,NULL,NULL,'2026-08-09','The PCL84 is a television triode and output pentode mainly for use as a video output stage.');
INSERT INTO "stock" VALUES(159,'PCL85','5',1,NULL,NULL,'2026-08-09','The PCL85 is a triode and output pentode combined.');
INSERT INTO "stock" VALUES(160,'PFL250','5',1,NULL,NULL,'2026-08-09','No information');
INSERT INTO "stock" VALUES(161,'PY800','5',3,NULL,NULL,'2026-08-09','The PY800 was one of the last rectifiers of its type to be developed and is based on the PY81 from 1952. It was specifically built as an efficiency diode for television line scan in sets using 110° deflection angle tubes.');
INSERT INTO "stock" VALUES(162,'PY801','5',1,NULL,NULL,'2026-08-09','The PY801 is a television efficiency diode for use in line timebase output circuits');
INSERT INTO "stock" VALUES(163,'PY81','5',1,NULL,NULL,'2026-08-09','an efficiency diode for television line scan and the design dates to the early 1950');
INSERT INTO "stock" VALUES(164,'ECL80','6',75,NULL,NULL,'2026-08-09','The ECL80 is a triode, output pentode for audio use.');
INSERT INTO "stock" VALUES(165,'6146','7',2,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(166,'6146B','7',8,NULL,NULL,'2026-08-09','popular small transmitting beam tetrode valve normally used in pairs within HF transmitters of 100 W outpu');
INSERT INTO "stock" VALUES(167,'6146W','7',2,NULL,NULL,'2026-08-09','6146 with performance under severe shock, military');
INSERT INTO "stock" VALUES(168,'12BY7','7',9,NULL,NULL,'2026-08-09','2BY7A was widely ised by radio amateurs in the 1960''s and 1970''s as a driver stage for a pair of 6146B');
INSERT INTO "stock" VALUES(169,'PL504','7',1,NULL,NULL,'2026-08-09','Pentode output valve -found their way into amateur radio transmitters for service at HF (up to 30 MHz) because of their peak voltage characteristics and relatively high current capability.');
INSERT INTO "stock" VALUES(170,'KT66','8',5,'GEC',NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(171,'R71','8',1,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(172,'KT66','8',1,'GEC','Loose Base','2026-08-09','loose base');
INSERT INTO "stock" VALUES(173,'GZ34','8',3,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(174,'EF86','8',6,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(175,'4CX250B','9',5,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(176,'4CX350','9',2,NULL,NULL,'2026-08-09','With Chimey and bases');
INSERT INTO "stock" VALUES(177,'7609','9',1,NULL,'Withbase','2026-08-09','withbase Rugged version 4cx150D');
INSERT INTO "stock" VALUES(178,'6442','9',1,NULL,'With Base','2026-08-09','with base The 6442 is a triode for grounded-grid operation. As an oscillator in a suitable cavity it can produce useful output at up to 5 GHz. This particular exhibit was employed as a driver stage in an AN/ARC-52 UHF set. The final power amplifier would have been something like a 4X150A and the modulator would be a pair of 2E26''s.');
INSERT INTO "stock" VALUES(179,'813','9',5,NULL,NULL,'2026-08-09','with 2 bases');
INSERT INTO "stock" VALUES(180,'807','9',3,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(181,'KT66','10',2,'Marshall','Matched Pair','2026-08-09','Matched Pair');
INSERT INTO "stock" VALUES(182,'KT66','10',4,'REC','Matched Quad','2026-08-09','Matched Quad');
INSERT INTO "stock" VALUES(183,'KT66','10',4,'Russian','Matched Quad','2026-08-09','Matched Quad');
INSERT INTO "stock" VALUES(184,'ECF80','11',13,NULL,NULL,'2026-08-09','a high slope RF pentode and not a variable μ type. The EF85 was the variable μ counterpart to the EF80.');
INSERT INTO "stock" VALUES(185,'EF85','11',27,NULL,NULL,'2026-08-09','The EF85 is a VHF variable μ pentode and is the counterpart to the EF80 straight RF pentode.');
INSERT INTO "stock" VALUES(186,'CV1375','11',1,NULL,NULL,'2026-08-09','EF85 Equiv');
INSERT INTO "stock" VALUES(187,'ECF80CV5215','11',5,NULL,NULL,'2026-08-09','ECF80');
INSERT INTO "stock" VALUES(188,'QS15015','11',1,NULL,NULL,'2026-08-09','miniature voltage stabiliser. The striking voltage is 170 and for burning currents of 2 - 10 mA the regulation is 5 Volts.');
INSERT INTO "stock" VALUES(189,'QQV026','11',1,NULL,NULL,'2026-08-09','ouble beam tetrodes in this 1950s series from Mullard. It was introduced for 470 MHz (UHF) mobile transmitters.');
INSERT INTO "stock" VALUES(190,'CV2799','11',1,NULL,NULL,'2026-08-09','double beam transmitting tetrode.');
INSERT INTO "stock" VALUES(191,'VR150','11',2,NULL,NULL,'2026-08-09','gas filled discharge tube that exhibits a near constant voltage across the valve for currents within the range 5mA to 40mA. In fact the regulation is 150 plus or minus 5.5 Volts.');
INSERT INTO "stock" VALUES(192,'QQV0640','11',1,NULL,NULL,'2026-08-09','ithin the envelope are two beam tetrodes with a maximum anode dissipation of 40 W.');
INSERT INTO "stock" VALUES(193,'5Y3','11',3,NULL,NULL,'2026-08-09','directly heated full wave rectifier, with inverted v''s of coated tape as filaments.');
INSERT INTO "stock" VALUES(194,'VT139','11',1,NULL,NULL,'2026-08-09','American version VR-150');
INSERT INTO "stock" VALUES(195,'VR10530','11',1,NULL,NULL,'2026-08-09','old cathode voltage stabiliser. The details of its operation are given in the type designation. This tube will stabilise the voltage across it to 105 Volts for output currents between 5 mA and 30 mA. To strike the tube the voltage must exceed 135 V.');
INSERT INTO "stock" VALUES(196,'EM84','11',2,NULL,NULL,'2026-08-09','tuning indicator, or magic eye, was used to display the optimum tuning point of a receiver, or the recording level of a tape recorder. The main benefit in reception was for FM radio where the exact tuning point was harder to determine than for AM.');
INSERT INTO "stock" VALUES(197,'EF89','11',7,NULL,NULL,'2026-08-09','miniature RF voltage amplifier. Mullard describe the EF89 as a variable μ pentode for use as an RF or IF amplifier in FM/AM receivers and is designed to work with a tuned anode circuit.');
INSERT INTO "stock" VALUES(198,'CV4014','11',6,NULL,NULL,'2026-08-09','UK service designation for the civilian M8083 or 6064, this in turn is a special quality version of the EF91 CV138. The M8083 has a more rugged build than the EF91 and was designed for operation in areas of vibration especially aircraft.');
INSERT INTO "stock" VALUES(199,'EF91','11',1,NULL,NULL,'2026-08-09','high gain, high impedance, high slope, screened pentode.');
INSERT INTO "stock" VALUES(200,'VT197','11',1,NULL,NULL,'2026-08-09','Version of 5y3');
INSERT INTO "stock" VALUES(201,'QQV310','11',6,NULL,NULL,'2026-08-09','double beam tetrode used in VHF transmitters');
INSERT INTO "stock" VALUES(202,'CV2466','11',1,NULL,NULL,'2026-08-09','UK Government designation for the commercial QQV02-6 designed by Mullard.');
INSERT INTO "stock" VALUES(203,'OB2','11',1,NULL,NULL,'2026-08-09','he regulation of this tube was 3.5 Volts for currents of between 5 and 30 mA. So the voltage across this tube in service would have been held at between 106 and 110 Volts. The striking voltage was 133 Volts.');
INSERT INTO "stock" VALUES(204,'CV287','11',1,NULL,NULL,'2026-08-09','miniature voltage stabiliser and its direct commercial equivalent is the QS150/15. The striking Voltage is 170 and for burning currents of 2 - 10 mA the regulation is 5 Volts.');
INSERT INTO "stock" VALUES(205,'CV1833','11',1,NULL,NULL,'2026-08-09','cold cathode voltage stabiliser and the CV specification took the OB2 as the prototype.');
INSERT INTO "stock" VALUES(206,'8136','12',11,NULL,NULL,'2026-08-09','The 8136 is a beam tetrode from the American General Electric corporation but is referred to as a pentode.');
INSERT INTO "stock" VALUES(207,'PL82','12',4,NULL,NULL,'2026-08-09','normally be found in audio stages of television receivers. A pair used in push pull class AB1 would deliver 9 Watts at 4 % distortion');
INSERT INTO "stock" VALUES(208,'30L1','12',6,NULL,NULL,'2026-08-09','double triode developed to meet the needs of VHF band III television transmission in the 1950s.');
INSERT INTO "stock" VALUES(209,'U26','12',4,NULL,NULL,'2026-08-09','purpose designed EHT rectifier for monochrome television picture tube supplies. The U26');
INSERT INTO "stock" VALUES(210,'150B2','12',10,NULL,NULL,'2026-08-09','50B2 voltage stabiliser has a striking voltage of 165 Volts and over the specified current range will regulate to 5 Volts of the 150 Volts.');
INSERT INTO "stock" VALUES(211,'DK91','12',7,NULL,NULL,'2026-08-09','miniature B7G dry battery heptode, it was designed for frequency changer use in battery portable radio receivers');
INSERT INTO "stock" VALUES(212,'6F1','12',4,NULL,NULL,'2026-08-09','The 6F1 is an amplifying pentode.');
INSERT INTO "stock" VALUES(213,'PCL84','12',8,NULL,NULL,'2026-08-09','a television triode and output pentode mainly for use as a video output stage.');
INSERT INTO "stock" VALUES(214,'DH77','12',8,NULL,NULL,'2026-08-09','The DH77 amplifier triode with twin signal diodes on a common cathode. It was designed for use in superhet receivers at the end of the IF chain and as the first audio amplifier feeding the output stage.');
INSERT INTO "stock" VALUES(215,'EF91','12',9,NULL,NULL,'2026-08-09','a high gain, high impedance, high slope, screened pentode.');
INSERT INTO "stock" VALUES(216,'D77','12',8,NULL,NULL,'2026-08-09','two separate signal diodes in the envelope.');
INSERT INTO "stock" VALUES(217,'6AU6','12',8,NULL,NULL,'2026-08-09','RF pentode for use up to 50 MHz.');
INSERT INTO "stock" VALUES(218,'6F23','12',4,NULL,NULL,'2026-08-09','screened amplifier pentode. The presence of two cathode connections suggests an RF role where lead inductance needs to kept to a minimum.');
INSERT INTO "stock" VALUES(219,'8D3','12',8,NULL,NULL,'2026-08-09','(EF91) universal amplifier pentode of the post war era, many manufacturers made versions of this standard valve. The version shown here was made by Brimar and is labelled for commercial use. The EF91 is a high gain, high impedance, sharp cut-off, screened pentode. It could be used from AF to VHF up to about 200 MHz and was found in large numbers in most types of electronic equipment.');
INSERT INTO "stock" VALUES(220,'U319','12',5,NULL,NULL,'2026-08-09','U319 is a half wave rectifier designed for 300 mA heater chain equipment.');
INSERT INTO "stock" VALUES(221,'EL95','12',6,NULL,NULL,'2026-08-09','EL95 is an output pentode with low heater consumption designed initially for car radios. It would also provide adequate audio power for a domestic receiver or smaller stereo system.');
INSERT INTO "stock" VALUES(222,'EC92','12',6,NULL,NULL,'2026-08-09','Single triode designed for use as a mixer, amplifier or oscillator in VHF television receivers.');
INSERT INTO "stock" VALUES(223,'EC91','12',8,NULL,NULL,'2026-08-09','miniature single triode. The Mullard manual describes the EC91 as a miniature screened triode for use as a grounded grid amplifier.');
INSERT INTO "stock" VALUES(224,'6F12','12',9,NULL,NULL,'2026-08-09','high gain, high impedance, high slope, screened pentode. The 6F12 was used in the 1948 Murphy V114 television receiver for RF and IF amplification.');
INSERT INTO "stock" VALUES(225,'DL96','12',6,NULL,NULL,'2026-08-09','audio output valve from Mullard''s low consumption dry battery valves from 1954. The audio output is low at 0.2 Watts but considering the low filament power it is quite remarkable.');
INSERT INTO "stock" VALUES(226,'PY4400','13',2,NULL,'Nos','2026-08-09','Penta Labs NOS');
INSERT INTO "stock" VALUES(227,'TY4125','14',1,'Mullard',NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(228,'SIMILAR','14',1,'Unmarked',NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(229,'150C4','14',2,'Mullard',NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(230,'4CX250B','15',1,NULL,NULL,'2026-08-09','Amperex');
INSERT INTO "stock" VALUES(231,'PL509','16',3,NULL,NULL,'2026-08-09','The PL509 was one of the last TV line timebase output pentode valves to be designed. The PL519 replaced the PL509 and was pin compatible. These valves were designed for service in colour television receivers employing shadow mask tubes. The EL509 differs only in heater requirements');
INSERT INTO "stock" VALUES(232,'30P4','16',8,NULL,NULL,'2026-08-09','The 30P4 from Mazda is a purpose designed line output valve. It was designed to deliver current pulses to the magnetic deflection coils wherein a linear rising magnetic field would be generated to drive the spot across the face of the tube.');
INSERT INTO "stock" VALUES(233,'7A7','16',4,NULL,NULL,'2026-08-09','Vacuum Pentode RF/IF-Stage Controlling (mu)');
INSERT INTO "stock" VALUES(234,'U191','16',4,NULL,NULL,'2026-08-09','The U191 is a television efficiency diode. The function of the device is to enable the stored energy of the line scan coils to be returned to the supply rail during flyback.');
INSERT INTO "stock" VALUES(235,'Z749','16',6,NULL,NULL,'2026-08-09','The Z749 is a screened amplifier pentode, the GEC name was used as the professional brand of M-OV. The Z749 is directly equivalent to the EF812 and closely related to the EF80. TV and radar receivers would require wide bandwidth RF amplification.');
INSERT INTO "stock" VALUES(236,'30L2','16',2,NULL,NULL,'2026-08-09','The 6/30L2 is a general purpose double triode with a screen between the sections. Their main applications are found in television receivers.');
INSERT INTO "stock" VALUES(237,'EB91','16',4,NULL,NULL,'2026-08-09','The EF91 is a high gain, high impedance, high slope, screened pentode. Mullard describe the EF91 as primarily intended for use as RF amplifiers or mixer valves');
INSERT INTO "stock" VALUES(238,'DY802','16',3,NULL,NULL,'2026-08-09','EHT Rectitfire fro BW TV maximum PIV of 30,000 Volts and will produce an output voltage of 20,000 Volts. The maximum reservoir capacitor is 0.003 μF.');
INSERT INTO "stock" VALUES(239,'EF80','16',10,NULL,NULL,'2026-08-09','internally screened pentode was a workhorse of the VHF TV receiver and was introduced in mid 1950 to replace the EF91. It was described by Mullard as: a high slope RF pentode and not a variable μ type');
INSERT INTO "stock" VALUES(240,'Z329','16',4,NULL,NULL,'2026-08-09','The Z329 is a miniature screened pentode that was designed to operate at the standard TV intermediate frequency of 33 MHz. The IF stages in any superhet receiver are where the main signal voltage amplification takes place.');
INSERT INTO "stock" VALUES(241,'PY81','16',6,NULL,NULL,'2026-08-09','The PY81 was specifically built as an efficiency diode for television line scan. The rectifier is specified as having a peak inverse voltage rating of 4,500 Volts, and a peak current rating of 450 mA.');
INSERT INTO "stock" VALUES(242,'30F5','16',3,NULL,NULL,'2026-08-09','The 30F5 is a miniature screened pentode that was designed to operate at the standard TV intermediate frequency of 33 MHz. T');
INSERT INTO "stock" VALUES(243,'CV4060','16',4,NULL,NULL,'2026-08-09','The CV4060 from AEI features a propane carbonised anode and dates from 1961. The commercial version is the S11E12. The screen grid is visible and is seen to be of wire stretched between side rods, the wire runs flat across the cathode. This valve was a purpose built series voltage regulator and so designed for a hard service life whilst supplying a regulated voltage to other stages in professional equipment.');
INSERT INTO "stock" VALUES(244,'ELC6J','16',1,NULL,NULL,'2026-08-09','Thyratron Xenon  Rectifier  - Peak Forward 750 Inverse 1250V Heater 2.5V 21 Amp, 6.4 Amps');
INSERT INTO "stock" VALUES(245,'BVA267','17',1,NULL,NULL,'2026-08-09','the EL33 audio output valve is the little brother of the EL37 with which it shares pin connections. Mullard describe this valve as a high sensitivity output pentode for use in AC mains equipment. The EL33 could be used in push pull to deliver 8 Watts');
INSERT INTO "stock" VALUES(246,'QP22B','17',1,NULL,NULL,'2026-08-09','The QP22B is a battery double pentode, designed for quiescent push pull class B audio amplification. Class B amplification produces considerable distortion at the points in the cycle where the valves move from cut-off to conduction. The advantage is that when not driven by a signal the power consumption from the HT battery is low. The total power output is 1 Watt and was aimed at driving a loudspeaker, quite a luxury when battery powered.');
INSERT INTO "stock" VALUES(247,'207','17',1,NULL,NULL,'2026-08-09','UNIDENTIFIED');
INSERT INTO "stock" VALUES(248,'PY33','17',1,NULL,NULL,'2026-08-09','The PY33 is an HT rectifier for television receivers. It operates directly from the mains input and with a series resistance of 25 Ohms it will feed a reservoir capacitor of 200 µF.');
INSERT INTO "stock" VALUES(249,'6SK7','17',1,NULL,NULL,'2026-08-09','The 6SK7 is a variable μ pentode for RF and IF amplifiers in superhet receivers. Essentially the S stands for single ended so the 6K7 had a top cap and this later development did not.');
INSERT INTO "stock" VALUES(250,'6J5','17',1,NULL,NULL,'2026-08-09','VT-94 / 6J5 is a classic general purpose triode design that is an improved version of the original 6C4 from RCA, and appears in many envelope shapes. In dual form the 6J5 becomes the 6SN7 double audio triode.');
INSERT INTO "stock" VALUES(251,'210HL','17',1,NULL,NULL,'2026-08-09','The 210HL from Cossor was listed in their 1935-6 manual and we have an advert for it from 1931. Cossor say of the 210HL that it probably the most popular valve in their battery series for use as a detector. Its characteristics are such as to suit it for use as a leaky grid detector in combination with small LF transformers. Under these conditions sufficient output is obtained to load a small output pentode or triode before overload occurs. In addition, the anode consumption is small, a consideration in receivers using HT batteries. The valve, in common with most other Cossor battery valves for use as HF or IF amplifiers, or as detectors, is fitted with seven point filament suspension. No microphony need therefore be feared as filament vibration is completely damped.');
INSERT INTO "stock" VALUES(252,'210SS','17',1,NULL,NULL,'2026-08-09','As Above, by Manufacturere Six Sixty. Second Quality outlet for Mullart');
INSERT INTO "stock" VALUES(253,'210','17',1,NULL,'Unmarked','2026-08-09',NULL);
INSERT INTO "stock" VALUES(254,'6K7','17',1,NULL,NULL,'2026-08-09','The 6K7 pentode was designed for intermediate frequency amplifiers in ''modern'' superhet type receivers during the mid 1930s.');
INSERT INTO "stock" VALUES(255,'PM1LF','17',1,NULL,NULL,'2026-08-09','Type PM1LF was first introduced in 1926');
INSERT INTO "stock" VALUES(256,'220HPT','17',1,NULL,NULL,'2026-08-09','The Cossor New Process 220HPT is a battery audio output pentode. The B4 and side terminal was released in 1932 with the B5 based version following the following year.');
INSERT INTO "stock" VALUES(257,'ECH35','17',1,NULL,NULL,'2026-08-09','he ECH35 is a typical triode hexode frequency changer or mixer for broadcast applications. The exhibit has the Mullard red paint external metallisation and for maximum isolation of the signal input and output circuits the hexode control grid is taken to the top cap.');
INSERT INTO "stock" VALUES(258,'TD22A','17',1,NULL,NULL,'2026-08-09','1934, The TDD2A is a double diode triode for battery receivers. The function was as detector, AGC rectifier and first audio voltage amplifier in a superhet broadcast receiver.');
INSERT INTO "stock" VALUES(259,'465A','17',1,NULL,'With Base','2026-08-09','With Base, Eimac 4-65A Transmitting Tetrode, Anode Disspation 65W, 120W Output');
INSERT INTO "stock" VALUES(260,'UBC81','17',1,NULL,NULL,'2026-08-09','small double diode triode was designed for signal demodulation and AGC detection in universal mains domestic equipment. The triode section could be used for a first stage of amplification after the detection process.');
INSERT INTO "stock" VALUES(261,'UL84','17',1,NULL,NULL,'2026-08-09','The Mullard EL84 is a classic audio pentode valve, immortalised in the 1950s 5-10 design for an audio amplifier. The UL84 was designed with a 100 mA heater, for use in universal voltage environments and thus with limited HT available. Our exhibit carries the Mullard logo but was not of UK manufacture.On a DC mains supply no transformer to increase the HT voltage is possible so the UL84 is designed to operate at lower anode voltages and increased anode current.');
INSERT INTO "stock" VALUES(262,'30C15','17',1,NULL,NULL,'2026-08-09','The 30C15 is a triode pentode designed for frequency changer use in VHF television receivers and is the high gain version of the 30C1.');
INSERT INTO "stock" VALUES(263,'6BW7','17',1,NULL,NULL,'2026-08-09','The 6BW7 is an internally screened pentode. It is the Brimar implementation of the standard valve, the Mullard EF80 is the more generally known type designatio');
INSERT INTO "stock" VALUES(264,'30PL14','17',1,NULL,NULL,'2026-08-09','Beam Tetrode, The 30PL14 like the 30PL13 and 30PL12 are dedicated frame output valves from the VHF TV era');
INSERT INTO "stock" VALUES(265,'P646','17',2,NULL,NULL,'2026-08-09','The EY87 is an EHT rectifier designed for EHT derived from the line timebase flyback. The DY87 has the same high voltage rating but has a 1.4 Volt 0.55 Amp heater. It is also for use in flyback generated EHT.');
INSERT INTO "stock" VALUES(266,'EF86','17',3,NULL,NULL,'2026-08-09','The EF86 is the standard early stage audio pre-amplifier valve. This exhibit was made by Mullard in Great Britain. Mullard designed the EF86 and it took over the frond end stage of audio amplifiers from the octal EF37A. It was first shown at the 1953 Radio Show and first used in their 5-10 amplifier from 1954.');
INSERT INTO "stock" VALUES(267,'UBC41','17',1,NULL,NULL,'2026-08-09','The UBC41 is an early all glass valve and less clear or free from imperfections than later valves. This is a double diode triode valve on a B8B base. Mullard describe the UBC41 as a high gain triode for use as an AF voltage amplifier, combined with twin diodes, for DC/AC mains operation.');
INSERT INTO "stock" VALUES(268,'PY81800','17',1,NULL,NULL,'2026-08-09','The PY80 is an early efficiency diode for television line scan systems and was part of the world series valves introduced by Mullard in 1950. Peak inverse voltage must be below 4KV');
INSERT INTO "stock" VALUES(269,'12BA6','17',1,NULL,NULL,'2026-08-09','The 12BA6 is described by Brimar as a variable μ pentode for use at HF within AC/DC receivers. Most probably as RF amplifiers.');
INSERT INTO "stock" VALUES(270,'6BW6','17',2,NULL,NULL,'2026-08-09','Type 6BW6 is essentially the once-ubiquitous Octal type 6V6G squeezed into a B9A envelope. The nominal ratings of the two types are identical. Not surprisingly, 6BW6s usually run (very) hot and require good ventilation if they are not to ''die'' prematurely.');
INSERT INTO "stock" VALUES(271,'PCC84','17',1,NULL,NULL,'2026-08-09','The PCC84 double triode shows how valves developed to meet the needs of VHF television transmission. The PCC84 and PCF80 both featured in set-top converters for the new ITV television Band III channels that commenced broadcasting in 1955. The transmissions were on around 170 MHz and much higher in frequency than the BBC Band I signals at around 50 MHz.');
INSERT INTO "stock" VALUES(272,'PCF802','17',1,NULL,NULL,'2026-08-09','The PCF802 was designed as the first stages in television line frequency generation prior to the line output stage. The pentode is described by Mullard as the oscillator while the triode is for service as a reactance valve. This suggests the triode acting as a frequency controlling stage.');
INSERT INTO "stock" VALUES(273,'PCL83','17',1,NULL,NULL,'2026-08-09','The PCL83 is a television triode output pentode. It is used as a frame timebase and frame output stage or audio output stage if required. It produces enough audio output power for an average domestic environment and was made from the early 1950s.');
INSERT INTO "stock" VALUES(274,'UAF42','17',1,NULL,NULL,'2026-08-09','The UAF42 is an early all glass valve introduced in 1948 together with the EAF42 and consists of a single diode and a variable μ RF amplifier pentode in a single envelope.');
INSERT INTO "stock" VALUES(275,'6AJ7','18',38,NULL,NULL,'2026-08-09','Pentode The 6AJ7 metal pentode was made in Canada for Marconi, and designed for high gain amplification');
INSERT INTO "stock" VALUES(276,'OV65','19',47,NULL,NULL,'2026-08-09','The 1938 Pen25 battery output pentode from Mazda was designed for domestic broadcast receivers. The filament was to be run from accumulators and the 0.15 Amp filament current would have assisted in prolonging the accumulator life.');
INSERT INTO "stock" VALUES(277,'KT61','20',1,NULL,NULL,'2026-08-09','Beam Tetrode: The KT61 audio output valve, part of a series of very successful valves from M-OV, features the standard 6.3 Volt heater that was introduced from America in the mid 1930''s.');
INSERT INTO "stock" VALUES(278,'PL509','20',3,NULL,NULL,'2026-08-09','The PL509 was one of the last TV line timebase output pentode valves to be designed. The PL519 replaced the PL509 and was pin compatible. These valves were designed for service in colour television receivers employing shadow mask tubes. The EL509 differs only in heater requirements. The normal anode voltage of 160 Volts is designed to be exceeded by pulses of up to 8,000 Volts and 1.4 Amps.');
INSERT INTO "stock" VALUES(279,'EA76','20',5,NULL,NULL,'2026-08-09','Diode: The EA76 was one of the first of the robust miniature types that were introduced by Mullard in 1950.');
INSERT INTO "stock" VALUES(280,'6AS6','20',1,NULL,NULL,'2026-08-09','The 6AS6 is a physically small amplifier pentode. It is designed for dual control and therefore the suppressor has a short grid base or control range.');
INSERT INTO "stock" VALUES(281,'6SN7','20',1,NULL,NULL,'2026-08-09','The 6SN7GT is a British made glass tubular version of this much loved double triode valve from the 1940''s.');
INSERT INTO "stock" VALUES(282,'N37','20',1,NULL,NULL,'2026-08-09','The N37 is a television type audio output pentode. The load impedance is 6000 Ohms and the cathode resistor is 330 Ohms. At 10% total harmonic distortion the valve can produce 2.3 watts of audio.');
INSERT INTO "stock" VALUES(283,'6AU5GT','20',1,NULL,NULL,'2026-08-09','The 6AU5GT is described as a beam pentode and was designed for line output service in television receivers. An alternate design use is as a series pass device in regulated power supplies.');
INSERT INTO "stock" VALUES(284,'PY801','20',1,NULL,NULL,'2026-08-09','The PY801 is a television efficiency diode for use in line timebase output circuits. Typically it will have a heater cathode insulation that is good to 6 kV and a peak current capability of 500 mA.');
INSERT INTO "stock" VALUES(285,'E80F','20',1,NULL,NULL,'2026-08-09','Pentode: The E80F is a Mullard special quality valve with a life longer than 10,000 hours. It was designed for audio amplifier use, normally in RC coupled designs');
INSERT INTO "stock" VALUES(286,'6AG7','20',1,NULL,NULL,'2026-08-09','Pentode: he 6AG7 is an American metal valve designed for single ended audio output stages. Probably for receiver use');
INSERT INTO "stock" VALUES(287,'EF184','20',2,NULL,NULL,'2026-08-09','The EF184 is a purpose designed high gain frame grid pentode. The EF184 superseded the ubiquitous EF80.');
INSERT INTO "stock" VALUES(288,'5642','20',2,NULL,NULL,'2026-08-09','The 5642 is an EHT rectifier diode designed specifically for use in oscilloscope EHT supplies and as a measuring instrument component it is a special quality device, the naming convention clearly shows this. The consumer DY70 is closely related to this special quality professional device.');
INSERT INTO "stock" VALUES(289,'6J6A','20',1,NULL,NULL,'2026-08-09','Twin Triodes');
INSERT INTO "stock" VALUES(290,'6CZ5','20',1,NULL,NULL,'2026-08-09','Beam Pentode Amplifier');
INSERT INTO "stock" VALUES(291,'CV5215','20',1,NULL,NULL,'2026-08-09','The CV5215 is a UK government code for the ECF80. The triode is the oscillator and has to produce 5 V pk-pk signal. The screened pentode is the mixer. The valve has two cathode connections so that the two valves can be used separately if required.');
INSERT INTO "stock" VALUES(292,'L776C4','20',2,NULL,NULL,'2026-08-09','The 6C4 triode valve was specified as both an amplifier and an RF power valve. In the latter role it would deliver 5.5 Watts in class C operation. With a very small envelope volume, this would make it ideal for hand portable equipment. In larger apparatus it could deliver enough drive power for much larger PA''s.');
INSERT INTO "stock" VALUES(293,'6BA6','20',1,NULL,NULL,'2026-08-09','The 6BA6 is described by Brimar as a variable μ pentode for use at HF. Most probably as RF amplifiers in radio receivers.');
INSERT INTO "stock" VALUES(294,'Z759','20',1,NULL,NULL,'2026-08-09','The Z759 is an RF pentode with a high mutual conductance designed for video or other wideband RF amplification.');
INSERT INTO "stock" VALUES(295,'ECF80','20',1,NULL,NULL,'2026-08-09','Brimar data sheets show this triode pentode valve as designed for VHF frequency changer use. Mullard say that the ECF80 was designed for operation up to 220 MHz.');
INSERT INTO "stock" VALUES(296,'ECC801','20',1,NULL,NULL,'2026-08-09','Double Triode at VHF');
INSERT INTO "stock" VALUES(297,'6V6','20',1,NULL,NULL,'2026-08-09','Beam Tetrode: he 6V6 family came in many constructions and were very popular as the final audio stage of broadcast receivers.');
INSERT INTO "stock" VALUES(298,'6GH8A','20',1,NULL,NULL,'2026-08-09','The 6GH8A is a triode pentode with separate cathodes designed for television receiver use. The valve is specified for multivibrator-type line deflection oscillators and/or AGC amplifier and sync-separator functions.');
INSERT INTO "stock" VALUES(299,'EY86','20',3,NULL,NULL,'2026-08-09','The EY86 is a television EHT rectifier is rated in terms of peak inverse volts (PIV) and that is quoted at 22,000 Volts. If fed from a sine wave the anode voltage would be limited to just under 8,000 Volts,');
INSERT INTO "stock" VALUES(300,'6X4','20',1,NULL,NULL,'2026-08-09','The 6X4 is a miniature HT rectifier following the normal pattern for a full wave device in that a common cathode is employed.');
INSERT INTO "stock" VALUES(301,'OA2','20',2,NULL,NULL,'2026-08-09','he 0A2 or OA2 is a cold cathode voltage stabiliser. The mean voltage stabilised is 150 Volts.');
INSERT INTO "stock" VALUES(302,'OB2','20',1,NULL,NULL,'2026-08-09','The regulation of this tube was 3.5 Volts for currents of between 5 and 30 mA. So the voltage across this tube in service would have been held at between 106 and 110 Volts. The striking voltage was 133 Volts.');
INSERT INTO "stock" VALUES(303,'EV3A','21',50,NULL,NULL,'2026-08-09','7 SEGMENT NIXI TUBE');
INSERT INTO "stock" VALUES(304,'VR150','22',7,NULL,NULL,'2026-08-09','The VR150 is a gas filled discharge tube that exhibits a near constant voltage across the valve for currents within the range 5mA to 40mA. In fact the regulation is 150 plus or minus 5.5 Volts.');
INSERT INTO "stock" VALUES(305,'6H2N','22',30,NULL,NULL,'2026-08-09','The 6N2P, (Russian: 6Н2П), also sometimes spelled in English "6H2Pi", is a miniature 9-pin dual triode vacuum tube manufactured in USSR, Russia and China with characteristics similar to the 12AX7. The most significant difference between the two is that 6N2P has its two filament elements connected in parallel, unlike the series filament connection of the 12AX7, and it is thus only possible to operate it from a 6.3 volt, 340 mA filament supply (whereas a 12AX7 may be operated from either 6.3 or 12.6 volts, at 300 mA or 150 mA, respectively.)');
INSERT INTO "stock" VALUES(306,'6H1NE8','23',10,NULL,NULL,'2026-08-09','f = 6.3 V, If = 600 mA');
INSERT INTO "stock" VALUES(307,'6C19N','23',8,NULL,NULL,'2026-08-09','Triode 6CI9n 6S19P');
INSERT INTO "stock" VALUES(308,'5U4C','23',6,NULL,NULL,'2026-08-09','Russian 5C4S rectifier tube is equivalent to the 5Z4 / CV1863 / 5Z4GT / 5U4C.');
INSERT INTO "stock" VALUES(309,'6N1N','24',10,NULL,NULL,'2026-08-09','The 6P1P (Russian: 6П1П) is a Soviet-made miniature 9-pin beam tetrode vacuum tube with ratings similar to the 6AQ5, EL90 and the 6V6. Because of a different pinout (a 9-pin base versus 7-pin base) than an 6AQ5/EL90, it cannot be used as a plug-in replacement for these types; however, it will work in the same circuit with component values unchanged. Its maximum plate/screen voltage and dissipation ratings are actually slightly higher than a 6AQ5. A ruggedized/extended ratings version of the tube is designated 6P1P-EV (Russian: 6П1П-ЕВ), roughly equivalent to the 6AQ5W. A Chinese-manufactured version of the tube also exists, labeled 6P1.');
INSERT INTO "stock" VALUES(310,'CF15N2','24',10,NULL,NULL,'2026-08-09','Striking voltage: 160V min,');
INSERT INTO "stock" VALUES(311,'6C17','24',30,NULL,NULL,'2026-08-09','Name: 6S17K-V;');
INSERT INTO "stock" VALUES(312,'GS14','24',8,NULL,NULL,'2026-08-09','he GS-14 titanium-ceramic triode generates, amplifies and multiplies oscillations on the centimetric and decimetric wavelength ranges.');
INSERT INTO "stock" VALUES(313,'6C51HB','24',4,NULL,NULL,'2026-08-09','6S51N');
INSERT INTO "stock" VALUES(314,'2XX27N','25',8,NULL,NULL,'2026-08-09','If you remove the aluminium screening case, you can discover a lovely valve inside.');
INSERT INTO "stock" VALUES(315,'EL84','25',4,NULL,NULL,'2026-08-09','2xzapex (GDR)');
INSERT INTO "stock" VALUES(316,'6P14P','25',4,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(317,'ECC8312AX7','25',4,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(318,'UCL83','25',1,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(319,'6C19N','26',12,NULL,NULL,'2026-08-09','he 6C19N / 6S19P Vacuum tube is a Russian Audiophile glass type power triode used in high-end amplifiers. They are used in the Transcendent Sound T16 OTL power amplifers among others, which uses an incredible 16 of these 6C19N / 6S19P tubes!');
INSERT INTO "stock" VALUES(320,'6J1P','26',4,NULL,NULL,'2026-08-09','The 6j1p is a high frequency pentode valve manufactured by the Voskhod factory in Russia. It is a seven-pin electronic component requiring a B7G base socket for connection, and 6.3 V for the heater filament. Using a 6j1p pentode as a triode is a very simple task, but unfortunately very few people understand how a pentode operates, however you might be wondering why use pentodes at all in the first place. Triodes are getting expensive due to their ever-dwindling stocks, and looking on eBay, the cost of a ECC81, ECC82, ECC83, and ECC85 has sky rocketed. However just recently I came across a cheap valve 6j1p selling for just one pound. It is very similar to the Russian 6z1p pentode and I was intrigued because there must be a factory out there making them!');
INSERT INTO "stock" VALUES(321,'GS15B','27',4,NULL,NULL,'2026-08-09','NameGS15BTypetetrodeCathode typesponged-metal,.oxide,indrect heatingApplication fieldoscillation and power amplification in common grid configuration in continous modeBrief applicationHF amplification, oscillationEnvelopemetal-ceramicCooling methodforced airDimensions69mmx37.1mmMass140 gFilament voltage6.3 VFilament current1.85 - 2.2 AMutual conductance9 mA/VOutput power200 WMaximum anode voltage11 kVMaximum operating frequency26 MHz');
INSERT INTO "stock" VALUES(322,'GI7B','28',4,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(323,'GI15B','28',1,NULL,NULL,'2026-08-09',NULL);
INSERT INTO "stock" VALUES(324,'6X4','29',1,NULL,NULL,'2026-08-09','The 6X4 is a miniature HT rectifier following the normal pattern for a full wave device in that a common cathode is employed. At 325-0-325 input to the rectifier this will give an HT rail higher than is required for most domestic receivers. Use for audio amplifiers and small transmitters is most probable, or driven at 250 Volts for radio receivers.');
INSERT INTO "stock" VALUES(325,'ECL80','29',8,NULL,NULL,'2026-08-09','The ECL80 is a triode, output pentode for audio use. The heater at 6.3 Volts and 300 mA makes this valve suitable for equipment with mains transformers and heater chains across the domestic mains.');
INSERT INTO "stock" VALUES(326,'UAF42','29',3,NULL,NULL,'2026-08-09','The UAF42 is an early all glass valve introduced in 1948 together with the EAF42 and consists of a single diode and a variable μ RF amplifier pentode in a single envelope.');
INSERT INTO "stock" VALUES(327,'150B2','29',1,NULL,NULL,'2026-08-09','The 150B2 voltage stabiliser has a striking voltage of 165 Volts and over the specified current range will regulate to 5 Volts of the 150 Volts');
INSERT INTO "stock" VALUES(328,'ECF80','29',2,NULL,NULL,'2026-08-09','The EF80 internally screened pentode was a workhorse of the VHF TV receiver and was introduced in mid 1950 to replace the EF91. It was described by Mullard as: a high slope RF pentode and not a variable μ type.');
INSERT INTO "stock" VALUES(329,'EF41','29',1,NULL,NULL,'2026-08-09','Mullard describe the EF41 as a variable μ RF pentode for use as an RF or IF amplifier');
INSERT INTO "stock" VALUES(330,'GZ34','29',1,NULL,NULL,'2026-08-09','he GZ34 is an example of a typical high current rectifier for small equipment use.');
INSERT INTO "stock" VALUES(331,'UF41','29',2,NULL,NULL,'2026-08-09','he UF41 from Mullard is a vari-mu amplifier pentode. Use was for AGC controlled RF and IF amplification in superhet receivers');
INSERT INTO "stock" VALUES(332,'UL41','29',1,NULL,NULL,'2026-08-09','The UL41 is an audio output pentode, and the design dates from 1947. The UL41 could produce 4.2 Watts at 10% distortion.');
INSERT INTO "stock" VALUES(333,'UBC41','29',2,NULL,NULL,'2026-08-09','The UBC41 is an early all glass valve and less clear or free from imperfections than later valves. This is a double diode triode valve on a B8B base. Mullard describe the UBC41 as a high gain triode for use as an AF voltage amplifier, combined with twin diodes, for DC/AC mains operation.');
INSERT INTO "stock" VALUES(334,'UCH42','29',2,NULL,NULL,'2026-08-09','The UCH42 is an early all glass triode hexode from 1948 and was designed as oscillator and mixer for superhet receivers, and the hexode section was designed to operate with an AGC control voltage.');
INSERT INTO "stock" VALUES(335,'75C1','29',1,NULL,NULL,'2026-08-09','The 75C1 is a high stability voltage stabiliser. The output voltage is 75 Volts and for currents of 2 - 60 mA the regulation is between 5 and 8 Volts.');
INSERT INTO "stock" VALUES(336,'UY41','29',2,NULL,NULL,'2026-08-09','The UY41 is a half wave rectifier designed for universal domestic equipment and replaced the UY21. By universal we mean AC or DC mains input and therefore no mains transformer.');
INSERT INTO "stock" VALUES(337,'7289','30',13,NULL,NULL,'2026-08-09','UHF Hi Mu Ceramic Triode, 6.3V at 1Amp 1KV, O/P around 50W good to 23CM and above');
INSERT INTO "stock" VALUES(338,'ACT22','30',2,NULL,NULL,'2026-08-09','UHF to about 30CM, Triode, Air cooled, good for a KW or so');
INSERT INTO "stock" VALUES(339,'5B251','30',11,NULL,NULL,'2026-08-09','Equiv 5B254 - basically a minature version of an 807');
INSERT INTO "stock" VALUES(340,'726A','30',3,NULL,NULL,'2026-08-09','Klystron This reflex klystron was designed for microwave RF generation of about 20 mW about 9.7 GHz. It produces a continuous output and can be modulated for communications use. The output power is taken from the probe by passing the tip into waveguide. The base for this valve is special but an International Octal holder with pin four drilled out is equivalent.');
INSERT INTO "stock" VALUES(341,'CV124','30',3,NULL,NULL,'2026-08-09','he CV124 beam tetrode valve is unusual in being designated as current production in the 1960s and having a five pin base. The commercial equivalent was the classic 807.');
INSERT INTO "stock" VALUES(342,'CV320','30',1,NULL,NULL,'2026-08-09','CRT Display');
