INSERT INTO "valve_type" VALUES('12BY7','12BY7','video/driver pentode',NULL,NULL,NULL,12.6,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2BY7A was widely ised by radio amateurs in the 1960''s and 1970''s as a driver stage for a pair of 6146B',NULL,NULL,NULL,'inferred',NULL);
