INSERT INTO "valve_type" VALUES('210','210',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Unmarked, Suspected to be 210',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('210HL','210HL',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 210HL from Cossor was listed in their 1935-6 manual and we have an advert for it from 1931. Cossor say of the 210HL that it probably the most popular valve in their battery series for use as a detector. Its characteristics are such as to suit it for use as a leaky grid detector in combination with small LF transformers. Under these conditions sufficient output is obtained to load a small output pentode or triode before overload occurs. In addition, the anode consumption is small, a consideration in receivers using HT batteries. The valve, in common with most other Cossor battery valves for use as HF or IF amplifiers, or as detectors, is fitted with seven point filament suspension. No microphony need therefore be feared as filament vibration is completely damped.','CV1050 CV2571 HL2K K30C K30D K30K PM2HL VT50',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('210SS','210 SS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'As Above, by Manufacturere Six Sixty. Second Quality outlet for Mullart',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('220HPT','220HPT',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The Cossor New Process 220HPT is a battery audio output pentode. The B4 and side terminal was released in 1932 with the B5 based version following the following year.','KT2',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('2C34','2C34','double triode (VHF)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4074A CV18 DET 19 VT224',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('2P29','2P29','RF/audio pentode',NULL,NULL,NULL,2.2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2.2v Heaters, Audio driver, high quality, 1-2 W out. HF capable Pentode',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('2XX27N','2XX27N','RF pentode',NULL,NULL,NULL,2.2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'If you remove the aluminium screening case, you can discover a lovely valve inside.','2J27P, 2Z27,2SH7',NULL,NULL,'inferred','Heater voltage: 2.2V | Heater current: 57mA | Anode voltage: 120V (200V maximum) | Anode current 1.9mA (2.5mA maximum) | Transconductance: 1.9mA/V');
INSERT INTO "valve_type" VALUES('30C15','30C15','triode-pentode (frequency changer)','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The 30C15 is a triode pentode designed for frequency changer use in VHF television receivers and is the high gain version of the 30C1.','9EN7 LZ339 PCF800',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30C17','30C17','triode-pentode (frequency changer)','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The 30C17 is a triode variable-mu pentode designed for television frequency changer use. When introduced it was the first variable μ TV frequency changer to be available in the UK.','PCF37',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30F5','30F5','RF pentode','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The 30F5 is a miniature screened pentode that was designed to operate at the standard TV intermediate frequency of 33 MHz. T','7ED7 PF818 Z329',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30FL1','30FL1','triode-tetrode','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The triode, low power beam tetrode was designed as a general purpose valve.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30FL14','30FL14','triode-tetrode','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The 30FL14 triode pentode offers high voltage gain in a screened design. It was probably designed for VHF television use',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30FL2','30FL2','triode-tetrode','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The 30FL2 is a television valve in a miniature envelope, the 6FL2 is identical except for the heater, which is 6.3 V at 0.5 A.  The triode, low power beam tetrode was designed as line time base and sync separator.','P728',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30L1','30L1','double triode / output','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The 30L1 is a double triode developed to meet the needs of VHF band III television transmission in the 1950s. designed for cascode operation. The normal configuration was for triode one to be operated as a grounded cathode stage directly coupled to triode two connected as a grounded grid stage',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30L17','30L17','double triode / output','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30L2','30L2','double triode / output','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The 6/30L2 is a general purpose double triode with a screen between the sections. Their main applications are found in television receivers.','6GA8 B729 ECC804',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30P12','30P12','output pentode/tetrode','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The 30P12 beam tetrode was designed as a single ended audio amplifier output valve for television receiver use or as a TV frame scan output valve.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('30P4','30P4','output pentode/tetrode','british (Mazda/Brimar code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The 30P4 from Mazda is a purpose designed line output valve. It was designed to deliver current pulses to the magnetic deflection coils wherein a linear rising magnetic field would be generated to drive the spot across the face of the tube.','25GF6, N308',NULL,NULL,'inferred',NULL);
