INSERT INTO "valve_type" VALUES('6442','JAN 6442',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'with base The 6442 is a triode for grounded-grid operation. As an oscillator in a suitable cavity it can produce useful output at up to 5 GHz. This particular exhibit was employed as a driver stage in an AN/ARC-52 UHF set. The final power amplifier would have been something like a 4X150A and the modulator would be a pair of 2E26''s.',NULL,NULL,NULL,'inferred','For microwave pulse operation, a 2 KW pulse is possible at 3.5 GHz or a wavelength of about 9');
INSERT INTO "valve_type" VALUES('6AG7','6AG7','output pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Pentode: he 6AG7 is an American metal valve designed for single ended audio output stages. Probably for receiver use','CV1882 VT-247',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6AJ7','6AJ7','RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Pentode The 6AJ7 metal pentode was made in Canada for Marconi, and designed for high gain amplification','6AC7 CV747 CV849',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6AS6','6AS6','RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6AS6 is a physically small amplifier pentode. It is designed for dual control and therefore the suppressor has a short grid base or control range.','409A 5725 6AS6W CV2522 CV4011',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6AU5GT','6AU5GT','beam pentode (line output)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6AU5GT is described as a beam pentode and was designed for line output service in television receivers. An alternate design use is as a series pass device in regulated power supplies.','6AU5',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6AU6','6AU6','RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'RF pentode for use up to 50 MHz.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6BA6','6BA6','variable-mu RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6BA6 is described by Brimar as a variable μ pentode for use at HF. Most probably as RF amplifiers in radio receivers.','5749 CV454 EF93 PM04 W727',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6BW6','6BW6','beam tetrode (output)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Type 6BW6 is essentially the once-ubiquitous Octal type 6V6G squeezed into a B9A envelope. The nominal ratings of the two types are identical. Not surprisingly, 6BW6s usually run (very) hot and require good ventilation if they are not to ''die'' prematurely.','CV2136 CV4043',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6BW7','6BW7','RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6BW7 is an internally screened pentode. It is the Brimar implementation of the standard valve, the Mullard EF80 is the more generally known type designatio','64SPT 6BX6 6F28 8D6 CV1376 EF80 Z152 Z719',NULL,NULL,'inferred',NULL);
