INSERT INTO "valve_type" VALUES('6F26','6F26','RF pentode','british (Mazda/Brimar code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6F26 is a VHF varible-mu pentode where the stage gain is controlled by the negative bias applied to the control grid.','EF183',NULL,NULL,'inferred',NULL);
