INSERT INTO "valve_type" VALUES('6F30','6F30','RF pentode','british (Mazda/Brimar code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'high gain VHF pentode. The mutual conductance is 15.6.','EF184',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6GH8A','6GH8A','triode + pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6GH8A is a triode pentode with separate cathodes designed for television receiver use. The valve is specified for multivibrator-type line deflection oscillators and/or AGC amplifier and sync-separator functions.','6EA8',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6H1NE8','6H1N-E8','double triode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6n1p',NULL,NULL,'inferred','μ = 35 | Ia = 7.5 mA | S = 4.35 mA/V | Pa = 2.2 W | The 6N1P has similar ratings to the 6DJ8 and in the past was sometimes rebranded as such, however differences between the two types (the 6N1P requires almost twice the filament current and has only one third the S value) mean they are not directly interchangeable. The S is about 4.35 ma/V, the 6DJ8/ECC88 has a S of 12.5 ma/V and a gain of 33 and a lower internal resistance. However, the 6N1P is typically more linear for a given load. It is therefore inaccurate to say that these two tubes are identical. The correct Russian equivalent to the 6DJ8/ECC88 is the 6N23P, the latter has a S of 12.5 mA/V and a gain of 33.');
INSERT INTO "valve_type" VALUES('6H2N','6H2N','double triode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6N2P, (Russian: 6Н2П), also sometimes spelled in English "6H2Pi", is a miniature 9-pin dual triode vacuum tube manufactured in USSR, Russia and China with characteristics similar to the 12AX7. The most significant difference between the two is that 6N2P has its two filament elements connected in parallel, unlike the series filament connection of the 12AX7, and it is thus only possible to operate it from a 6.3 volt, 340 mA filament supply (whereas a 12AX7 may be operated from either 6.3 or 12.6 volts, at 300 mA or 150 mA, respectively.)','6N2P',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6J1P','6J1P','RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6j1p is a high frequency pentode valve manufactured by the Voskhod factory in Russia. It is a seven-pin electronic component requiring a B7G base socket for connection, and 6.3 V for the heater filament. Using a 6j1p pentode as a triode is a very simple task, but unfortunately very few people understand how a pentode operates, however you might be wondering why use pentodes at all in the first place. Triodes are getting expensive due to their ever-dwindling stocks, and looking on eBay, the cost of a ECC81, ECC82, ECC83, and ECC85 has sky rocketed. However just recently I came across a cheap valve 6j1p selling for just one pound. It is very similar to the Russian 6z1p pentode and I was intrigued because there must be a factory out there making them!',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6J5','6J5','triode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'VT-94 / 6J5 is a classic general purpose triode design that is an improved version of the original 6C4 from RCA, and appears in many envelope shapes. In dual form the 6J5 becomes the 6SN7 double audio triode.','6C5 CV1933 VT-94',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6J6A','6J6A','double triode (VHF)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6J9P','6J9P','RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Equiv E180F, HF Pentode, 6.3V',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6K7','6K7','variable-mu RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6K7 pentode was designed for intermediate frequency amplifiers in ''modern'' superhet type receivers during the mid 1930s.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6N1N','6N1N','beam tetrode (output)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6P1P (Russian: 6П1П) is a Soviet-made miniature 9-pin beam tetrode vacuum tube with ratings similar to the 6AQ5, EL90 and the 6V6. Because of a different pinout (a 9-pin base versus 7-pin base) than an 6AQ5/EL90, it cannot be used as a plug-in replacement for these types; however, it will work in the same circuit with component values unchanged. Its maximum plate/screen voltage and dissipation ratings are actually slightly higher than a 6AQ5. A ruggedized/extended ratings version of the tube is designated 6P1P-EV (Russian: 6П1П-ЕВ), roughly equivalent to the 6AQ5W. A Chinese-manufactured version of the tube also exists, labeled 6P1.','6p1p',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6N2P','6N2P','double triode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Dual Triode, 6.3V heater, like 12AX7 - with slight differences in pins.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6P14P','6P14P','output pentode/beam tetrode','russian',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'EL84 Equiv',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6SK7','6SK7','variable-mu RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6SK7 is a variable μ pentode for RF and IF amplifiers in superhet receivers. Essentially the S stands for single ended so the 6K7 had a top cap and this later development did not.','CV1981 VT-117',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6SN7','6SN7','double triode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6SN7GT is a British made glass tubular version of this much loved double triode valve from the 1940''s.','13D2 B65 CV1988 VT-231',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6V6','6V6','beam tetrode (output)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Beam Tetrode: he 6V6 family came in many constructions and were very popular as the final audio stage of broadcast receivers.','CV510 VT-107',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6X4','6X4','full-wave rectifier',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6X4 is a miniature HT rectifier following the normal pattern for a full wave device in that a common cathode is employed. At 325-0-325 input to the rectifier this will give an HT rail higher than is required for most domestic receivers. Use for audio amplifiers and small transmitters is most probable, or driven at 250 Volts for radio receivers.','6063 CV493 EZ90 U78',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('726A','726A','reflex klystron',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Klystron This reflex klystron was designed for microwave RF generation of about 20 mW about 9.7 GHz. It produces a continuous output and can be modulated for communications use. The output power is taken from the probe by passing the tip into waveguide. The base for this valve is special but an International Octal holder with pin four drilled out is equivalent.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('7289','JAN 7289','UHF ceramic triode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'UHF Hi Mu Ceramic Triode, 6.3V at 1Amp 1KV, O/P around 50W good to 23CM and above','2c39A',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('75C1','75C1','voltage stabiliser (cold cathode)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 75C1 is a high stability voltage stabiliser. The output voltage is 75 Volts and for currents of 2 - 60 mA the regulation is between 5 and 8 Volts.',NULL,NULL,NULL,'inferred',NULL);
