INSERT INTO "valve_type" VALUES('8D3','8D3','RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(EF91) universal amplifier pentode of the post war era, many manufacturers made versions of this standard valve. The version shown here was made by Brimar and is labelled for commercial use. The EF91 is a high gain, high impedance, sharp cut-off, screened pentode. It could be used from AF to VHF up to about 200 MHz and was found in large numbers in most types of electronic equipment.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('ACT22','ACT 22','power triode (UHF)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'UHF to about 30CM, Triode, Air cooled, good for a KW or so','RV1493',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('BVA267','BVA 267','signal diode','european (Mullard/Philips code)',NULL,NULL,NULL,0.18,NULL,NULL,NULL,NULL,NULL,NULL,'the EL33 audio output valve is the little brother of the EL37 with which it shares pin connections. Mullard describe this valve as a high sensitivity output pentode for use in AC mains equipment. The EL33 could be used in push pull to deliver 8 Watts','BVA267 = EL33 = BVA264 = BVA265',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('CF15N2','CF15N-2','voltage stabiliser (cold cathode)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Striking voltage: 160V min,','SG15P',NULL,NULL,'inferred','Operating voltage : 105V (102-110V), | Operating current: 5mA to 30mA.');
INSERT INTO "valve_type" VALUES('CV124','CV124','beam tetrode (transmitting)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'he CV124 beam tetrode valve is unusual in being designated as current production in the 1960s and having a five pin base. The commercial equivalent was the classic 807.','807',NULL,NULL,'inferred',NULL);
