INSERT INTO "valve_type" VALUES('CV2466','CV2466','double beam tetrode (transmitting)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'UK Government designation for the commercial QQV02-6 designed by Mullard.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('CV2799','CV2799','double beam tetrode (transmitting)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'double beam transmitting tetrode.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('CV287','CV287','voltage stabiliser (cold cathode)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'miniature voltage stabiliser and its direct commercial equivalent is the QS150/15. The striking Voltage is 170 and for burning currents of 2 - 10 mA the regulation is 5 Volts.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('CV320','CV320','cathode ray tube',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('CV4014','CV4014','RF pentode (special quality)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The CV4014 is a UK service designation for the civilian M8083 or 6064, this in turn is a special quality version of the EF91 CV138. The M8083 has a more rugged build than the EF91 and was designed for operation in areas of vibration especially aircraft.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('CV4060','CV4060','RF pentode (special quality)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The CV4060 from AEI features a propane carbonised anode and dates from 1961. The commercial version is the S11E12. The screen grid is visible and is seen to be of wire stretched between side rods, the wire runs flat across the cathode. This valve was a purpose built series voltage regulator and so designed for a hard service life whilst supplying a regulated voltage to other stages in professional equipment.','7971 CV4060 CV8077 L.5B/280K',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('CV5215','CV5215','triode + pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The CV5215 is a UK government code for the ECF80. The triode is the oscillator and has to produce 5 V pk-pk signal. The screened pentode is the mixer. The valve has two cathode connections so that the two valves can be used separately if required.','6BL8 6C16 ECF80',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('D77','D77','diode','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The D77 is the Marconi equivalent of the Mullard EB91, and consists of two separate signal diodes in the envelope',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('DAF96','DAF96','signal diode + pentode','european (Mullard/Philips code)',NULL,NULL,1.4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Detector, First Audio stage, Low Current consumption',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('DF96','DF96','pentode','european (Mullard/Philips code)',NULL,NULL,1.4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Pentode, IF Amplifier, Low Current Consumption',NULL,NULL,NULL,'inferred',NULL);
