INSERT INTO "valve_type" VALUES('DK91','DK91','octode','european (Mullard/Philips code)',NULL,NULL,1.4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'miniature B7G dry battery heptode, it was designed for frequency changer use in battery portable radio receivers',NULL,NULL,NULL,'inferred',NULL);
