INSERT INTO "valve_type" VALUES('DL96','DL96','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,1.4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'audio output valve from Mullard''s low consumption dry battery valves from 1954. The audio output is low at 0.2 Watts but considering the low filament power it is quite remarkable.',NULL,NULL,NULL,'inferred',NULL);
