INSERT INTO "valve_type" VALUES('DY86','DY86','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,1.4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The DY86 is a television EHT rectifier. It was designed to have its heater supply produced by an overwind on the line output transformer. The 18,000 Volt rating places this as a rectifier for medium sized monochrome televisions.',NULL,NULL,NULL,'inferred',NULL);
