INSERT INTO "valve_type" VALUES('EF183','EF183','pentode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The EF183 is a high gain variable μ RF amplifier pentode. It is a late 1950s design and superseded the EF85. The EF184 was the straight version of the design and replaced the EF80. All four valves have the same pin connections.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('EF184','EF184','pentode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The EF184 is a purpose designed high gain frame grid pentode. The EF184 superseded the ubiquitous EF80.','6EJ7 6F30 CV5810',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('EF41','EF41','pentode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Mullard describe the EF41 as a variable μ RF pentode for use as an RF or IF amplifier',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('EF80','EF80','pentode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'internally screened pentode was a workhorse of the VHF TV receiver and was introduced in mid 1950 to replace the EF91. It was described by Mullard as: a high slope RF pentode and not a variable μ type','64SPT 6BX6 8D6 CV1376 Z152 Z719',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('EF85','EF85','pentode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The EF85 is a VHF variable μ pentode and is the counterpart to the EF80 straight RF pentode.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('EF86','EF86','pentode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The EF86 is the standard early stage audio pre-amplifier valve. This exhibit was made by Mullard in Great Britain. Mullard designed the EF86 and it took over the frond end stage of audio amplifiers from the octal EF37A. It was first shown at the 1953 Radio Show and first used in their 5-10 amplifier from 1954.','6267 6BK8 6F22 CV2901 Z729',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('EF89','EF89','pentode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'miniature RF voltage amplifier. Mullard describe the EF89 as a variable μ pentode for use as an RF or IF amplifier in FM/AM receivers and is designed to work with a tuned anode circuit.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('EF91','EF91','pentode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The EF91 is a high gain, high impedance, high slope, screened pentode. Mullard describe the EF91 as primarily intended for use as RF amplifiers or mixer valves in television receivers.',NULL,NULL,NULL,'inferred',NULL);
