INSERT INTO "valve_type" VALUES('EL41','EL41','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The EL41 is an early all glass output pentode. Mullard describe the EL41 as an output pentode rated for 9 watts anode dissipation, and intended primarily for use in AC mains operated equipment. They state that the EL41 should only be used with self-bias or semi-automatic bias',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('EL84','EL84','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2xMullard, 2xPinnacle,1XTEONEX',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('EL95','EL95','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'EL95 is an output pentode with low heater consumption designed initially for car radios. It would also provide adequate audio power for a domestic receiver or smaller stereo system.',NULL,NULL,NULL,'inferred',NULL);
