INSERT INTO "valve_type" VALUES('EM84','EM84','tuning indicator','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'tuning indicator, or magic eye, was used to display the optimum tuning point of a receiver, or the recording level of a tape recorder. The main benefit in reception was for FM radio where the exact tuning point was harder to determine than for AM.',NULL,NULL,NULL,'inferred',NULL);
