INSERT INTO "valve_type" VALUES('EY86','EY86','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The EY86 is a television EHT rectifier is rated in terms of peak inverse volts (PIV) and that is quoted at 22,000 Volts. If fed from a sine wave the anode voltage would be limited to just under 8,000 Volts,','6S2 CV2966',NULL,NULL,'inferred',NULL);
