INSERT INTO "valve_type" VALUES('KT61','KT61','beam tetrode (output)','british (GEC)',NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Beam Tetrode: The KT61 audio output valve, part of a series of very successful valves from M-OV, features the standard 6.3 Volt heater that was introduced from America in the mid 1930''s.','6AG6 6P25 CV1438 CV2938 EL33 N147 OM9',NULL,NULL,'inferred',NULL);
