INSERT INTO "valve_type" VALUES('L776C4','L77/6C4',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6C4 triode valve was specified as both an amplifier and an RF power valve. In the latter role it would deliver 5.5 Watts in class C operation. With a very small envelope volume, this would make it ideal for hand portable equipment. In larger apparatus it could deliver enough drive power for much larger PA''s.','CV133 CV852 EC90 L77 V741',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('N37','N37','output pentode','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The N37 is a television type audio output pentode. The load impedance is 6000 Ohms and the cathode resistor is 330 Ohms. At 10% total harmonic distortion the valve can produce 2.3 watts of audio.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('OA2','OA2','voltage stabiliser (cold cathode)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'he 0A2 or OA2 is a cold cathode voltage stabiliser. The mean voltage stabilised is 150 Volts.','150C2 CV1832 CV1832 GD150M QS1207 VR150MT',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('OB2','OB2','voltage stabiliser (cold cathode)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The regulation of this tube was 3.5 Volts for currents of between 5 and 30 mA. So the voltage across this tube in service would have been held at between 106 and 110 Volts. The striking voltage was 133 Volts.','108C1 108C1 6074 CV1833 CV1833 G108/1K QS1208',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('OV65','OV65','output pentode (battery)',NULL,NULL,NULL,2.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 1938 Pen25 battery output pentode from Mazda was designed for domestic broadcast receivers. The filament was to be run from accumulators and the 0.15 Amp filament current would have assisted in prolonging the accumulator life.','OV65 cv65 PEN 25, 211 242C 4242A ES85 UE311',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('P646','P646',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The EY87 is an EHT rectifier designed for EHT derived from the line timebase flyback. The DY87 has the same high voltage rating but has a 1.4 Volt 0.55 Amp heater. It is also for use in flyback generated EHT.','EY86 = EY87',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PC86','PC86','triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PC86 is a purpose designed UHF oscillator triode for television reception',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PC88','PC88','triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PC88 is a UHF triode designed for grounded grid operation in the front end RF amplifier in Band IV and Band V television tuners',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PC900','PC900','triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PC900 is a miniature VHF amplifier triode for use as an RF amplifier in television receivers. It is low impedance and has a high mutual conductance.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PC97','PC97','triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PC97 is a VHF triode. It has a high mutual conductance and could be used as a signal pre-amplifier.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCC189','PCC189','double triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PCC189 is a low impedance high gain double triode for use as a cascode amplifier in television front-ends. It specifically states that it is built with frame grids. The valves are variable μ types for use at RF as AGC controlled devices.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCC84','PCC84','double triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PCC84 double triode shows how valves developed to meet the needs of VHF television transmission. The PCC84 and PCF80 both featured in set-top converters for the new ITV television Band III channels that commenced broadcasting in 1955. The transmissions were on around 170 MHz and much higher in frequency than the BBC Band I signals at around 50 MHz.','30L1 7AN7 B319 CV5191',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCC85','PCC85','double triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCF210','PCF210','triode + pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCF80','PCF80','triode + pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The valve is a triode pentode, with separate cathodes, designed to function as a mixer and oscillator in the tuner.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCF801','PCF801','triode + pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PCF801 is a television mixer oscillator. Triode pentode combinations worked better at high frequencies than hexode mixers.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCF802','PCF802','triode + pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PCF802 was designed as the first stages in television line frequency generation prior to the line output stage. The pentode is described by Mullard as the oscillator while the triode is for service as a reactance valve. This suggests the triode acting as a frequency controlling stage.','9JW8',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCF805','PCF805','triode + pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'purpose designed oscillator and mixer for frequency changer use in VHF television receivers.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCF806','PCF806','triode + pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'triode and frame-grid pentode frequency changer for VHF television receivers up to 220 MHz.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCF905','PCF905','triode + pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'No information, maybe PCF805 t is a purpose designed oscillator and mixer for frequency changer use in VHF television receivers.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCH200','PCH200','triode + hexode/heptode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'triode heptode. The triode was designed as a pulse amplifier and the heptode section was designed for service as a noise gated sync. separator in colour television receivers.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCH84','PCH84','triode + hexode/heptode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PCF84 is triode pentode oscillator and mixer for the front ends of VHF television sets.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCL800','PCL800','triode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'Triode output pentode designed for field timebase or audio service. The PCL800 is a television receiver valve with a 300 mA heater for use with series heater chains. Domestic televisions worked at mains voltage and did not have a mains transformer.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCL805','PCL805','triode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'triode pentode was purpose designed as a domestic television receiver frame output stage.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCL80585','PCL805/85',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The PCL85 is a triode and output pentode combined.','12GV8',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCL82','PCL82','triode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PCL82 triode pentode is typical of valve television receivers audio output stages',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCL83','PCL83','triode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PCL83 is a television triode output pentode. It is used as a frame timebase and frame output stage or audio output stage if required. It produces enough audio output power for an average domestic environment and was made from the early 1950s.','CV5144 LN309',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCL84','PCL84','triode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PCL84 is a television triode and output pentode mainly for use as a video output stage.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCL85','PCL85','triode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PCL85 is a triode and output pentode combined.','12GV8',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PCL86','PCL86','triode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'This PCL86 was made in the UK by Mullard and was designed for the audio stage of a television receiver and offered a quality output at about 4W. Pentode, Triode.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PF200','PF200','pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PFL200 combines a screened amplifier pentode and an output pentode in the one envelope. It was designed for television use, but probably not for audio output as the operating conditions do not give an output power. The mutual conductance of the output pentode at 21 is very high, pointing to a very small space between cathode and control grid.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PFL200','PFL200','pentode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'two separate pentode valves in one package. For consumer electronics products cost reduction was vital, and the more functionality within each envelope the bette',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PFL250','PFL250','pentode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PL504','PL504','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'Pentode output valve -found their way into amateur radio transmitters for service at HF (up to 30 MHz) because of their peak voltage characteristics and relatively high current capability.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PL509','PL509','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PL509 was one of the last TV line timebase output pentode valves to be designed. The PL519 replaced the PL509 and was pin compatible. These valves were designed for service in colour television receivers employing shadow mask tubes. The EL509 differs only in heater requirements. The normal anode voltage of 160 Volts is designed to be exceeded by pulses of up to 8,000 Volts and 1.4 Amps.','40KG6, 40KG6A',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PL802','PL802','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'purpose designed video output pentode for driving a cathode ray tube with the wide bandwidth signal needed for colour TV picture information. 300V at 6 watts',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PL81','PL81','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PL81 Line Ouput, 6KV was designed for universal mains sets without a mains transformer and with the heaters on a series chain. The parameters given are for a pair in push pull audio service.','21A6',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PL82','PL82','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'normally be found in audio stages of television receivers. A pair used in push pull class AB1 would deliver 9 Watts at 4 % distortion',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PL83','PL83','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'This is a true pentode with three wire grids. Used for video amplifier',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PL84','PL84','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'audio output pentode was designed for use in television receivers. Like the UL84 with a 100mA heater it is a low voltage high current version of the EL84, itself a standard in design.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PM1LF','PM1LF',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Type PM1LF was first introduced in 1926','210LF CV3642 L210',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY33','PY33','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PY33 is an HT rectifier for television receivers. It operates directly from the mains input and with a series resistance of 25 Ohms it will feed a reservoir capacitor of 200 µF.','PY32 U291',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY4400','PY 4-400','power tetrode (transmitting)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY80','PY80','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PY80 is an early efficiency diode for television line scan systems and was part of the world series valves introduced by Mullard in 1950. The maximum peak inverse voltage on the anode has to be under 4 kV. The peak heater to cathode voltage has to be under 650 Volts.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY800','PY800','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PY800 was one of the last rectifiers of its type to be developed and is based on the PY81 from 1952. It was specifically built as an efficiency diode for television line scan in sets using 110° deflection angle tubes.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY801','PY801','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PY801 is a television efficiency diode for use in line timebase output circuits. Typically it will have a heater cathode insulation that is good to 6 kV and a peak current capability of 500 mA.','A61 U193 U349',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY802','PY802','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY81','PY81','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PY81 was specifically built as an efficiency diode for television line scan. The rectifier is specified as having a peak inverse voltage rating of 4,500 Volts, and a peak current rating of 450 mA.','17Z3 PY800 U153 U329',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY81800','PY81/800',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The PY80 is an early efficiency diode for television line scan systems and was part of the world series valves introduced by Mullard in 1950. Peak inverse voltage must be below 4KV','19X3 U152 U309',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY82','PY82','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PY82 is an efficiency diode for use in domestic television receivers.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY83','PY83','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'The PY83 is an efficiency diode for use in television line scan circuits. The peak inverse anode voltage is 5,600 Volts and peak current is 500 mA.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY86','PY86','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('PY88','PY88','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.3,NULL,NULL,NULL,NULL,NULL,NULL,'he PY88 is an efficiency diode for use in television line scan systems, where stored energy in the inductances is returned to the HT rail capacitors. The maximum peak inverse voltage (PIV) rating is 6,600 Volts. The peak anode current is 550 mA. These diodes require a very good heater cathode insulation and the PY88 is rated at 6,600 Volts.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('QP22B','QP22B','double pentode (QPP output)','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The QP22B is a battery double pentode, designed for quiescent push pull class B audio amplification. Class B amplification produces considerable distortion at the points in the cycle where the valves move from cut-off to conduction. The advantage is that when not driven by a signal the power consumption from the HT battery is low. The total power output is 1 Watt and was aimed at driving a loudspeaker, quite a luxury when battery powered.','240QP K77B',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('QQV026','QQV02-6','double beam tetrode','transmitting',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ouble beam tetrodes in this 1950s series from Mullard. It was introduced for 470 MHz (UHF) mobile transmitters.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('QQV0640','QQV06-40','double beam tetrode','transmitting',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ithin the envelope are two beam tetrodes with a maximum anode dissipation of 40 W.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('QQV310','QQV3-10','double beam tetrode','transmitting',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'double beam tetrode used in VHF transmitters',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('QS15015','QS 150/15','voltage stabiliser (cold cathode)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'miniature voltage stabiliser. The striking voltage is 170 and for burning currents of 2 - 10 mA the regulation is 5 Volts.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('QY3125','QY3-125','power tetrode (transmitting)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('R71','R71','rectifier',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('SIMILAR','?(SIMILAR)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('TD22A','TD22A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1934, The TDD2A is a double diode triode for battery receivers. The function was as detector, AGC rectifier and first audio voltage amplifier in a superhet broadcast receiver.','AR10 CV1308 CV3726 HD24 L21/DD',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('TY4125','TY4-125','power tetrode (transmitting)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('U191','U191','rectifier','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The U191 is a television efficiency diode. The function of the device is to enable the stored energy of the line scan coils to be returned to the supply rail during flyback.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('U25','U25','rectifier','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The U25 is a dedicated television EHT rectifier for picture tube supplies. The Mullard code for this valve would be KY50 but U25 was the standard name. The valve is rated at 19 kV peak inverse volts',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('U26','U26','rectifier','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'purpose designed EHT rectifier for monochrome television picture tube supplies. The U26',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('U282','U282','rectifier','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The U282 is a television efficiency diode, used to return energy from the collapsing field in the line coils to the HT rail. The peak current is given as 600 mA',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('U319','U319','rectifier','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'U319 is a half wave rectifier designed for 300 mA heater chain equipment.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UABC80','UABC80','signal diode + double diode + triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'The UABC80 is a triple diode triode',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UAF42','UAF42','signal diode + pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'The UAF42 is an early all glass valve introduced in 1948 together with the EAF42 and consists of a single diode and a variable μ RF amplifier pentode in a single envelope.','12S7 WD142',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UBC41','UBC41','double diode + triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'The UBC41 is an early all glass valve and less clear or free from imperfections than later valves. This is a double diode triode valve on a B8B base. Mullard describe the UBC41 as a high gain triode for use as an AF voltage amplifier, combined with twin diodes, for DC/AC mains operation.','10LD3 141DDT 14L7 DH118 DH142',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UBC81','UBC81','double diode + triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'small double diode triode was designed for signal demodulation and AGC detection in universal mains domestic equipment. The triode section could be used for a first stage of amplification after the detection process.','10LD13 DH119',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UCC85','UCC85','double triode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'The UCC85 is the universal supply version of the ECC85 VHF double triode, designed for RF amplifier and local oscillator use in FM radio receivers.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UCH42','UCH42','triode + hexode/heptode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'The UCH42 is an early all glass triode hexode from 1948 and was designed as oscillator and mixer for superhet receivers, and the hexode section was designed to operate with an AGC control voltage.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UCH81','UCH81','triode + hexode/heptode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UCL83','UCL83','triode + output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The UCL83 is an AF amplifier triode and an output pentode combined in a single envelope. The use would have been for post detector amplification and loudspeaker driving in broadcast receivers and small VHF televisions sets. The 100 mA heater is for use on heater chains in universal AC or DC mains equipment',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UF41','UF41','pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'he UF41 from Mullard is a vari-mu amplifier pentode. Use was for AGC controlled RF and IF amplification in superhet receivers',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UF89','UF89','pentode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UL41','UL41','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'The UL41 is an audio output pentode from 1953. The U series were designed to operate with a heater chain across the mains in the days when AC mains had not reached all parts of the country. These universal sets contained no mains transformers and the valves were designed for low anode voltage and higher anode current to provide adequate output. The UL41 could produce 4.2 Watts at 10% distortion.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UL84','UL84','output pentode/tetrode','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'The Mullard EL84 is a classic audio pentode valve, immortalised in the 1950s 5-10 design for an audio amplifier. The UL84 was designed with a 100 mA heater, for use in universal voltage environments and thus with limited HT available. Our exhibit carries the Mullard logo but was not of UK manufacture.On a DC mains supply no transformer to increase the HT voltage is possible so the UL84 is designed to operate at lower anode voltages and increased anode current.','6BQ5 6P15 CV2975 N709',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UY41','UY41','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'The UY41 is a half wave rectifier designed for universal domestic equipment and replaced the UY21. By universal we mean AC or DC mains input and therefore no mains transformer.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('UY85','UY85','HV half-wave rectifier','european (Mullard/Philips code)',NULL,NULL,NULL,0.1,NULL,NULL,NULL,NULL,NULL,NULL,'The UY85 is a half wave rectifier and would be used on small universal (AC/DC) mains appliances. The heater chain would draw 100 mA and this was to enable the small number of valves used in a broadcast radio receiver to be run without a large dropper (ballast) resister.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('VR10530','VR 105/30',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'old cathode voltage stabiliser. The details of its operation are given in the type designation. This tube will stabilise the voltage across it to 105 Volts for output currents between 5 mA and 30 mA. To strike the tube the voltage must exceed 135 V.',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('VR150','VR-150','voltage stabiliser (cold cathode)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The VR150 is a gas filled discharge tube that exhibits a near constant voltage across the valve for currents within the range 5mA to 40mA. In fact the regulation is 150 plus or minus 5.5 Volts.','0D3 150C3 CV216 CV685 G150/3D G180/2D GD150A/S GL150/30 KD25 QS150/40 VT-139 WT-294',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('VT139','VT-139',NULL,'european (Mullard/Philips code)',NULL,NULL,NULL,0.05,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('VT197','VT197',NULL,'european (Mullard/Philips code)',NULL,NULL,NULL,0.05,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('VT61A','VT61A','double triode (VHF)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'inferred','VHF | VT61A | Double Triode | 15W output | 150Mhz');
INSERT INTO "valve_type" VALUES('Z329','Z329','RF pentode','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The Z329 is a miniature screened pentode that was designed to operate at the standard TV intermediate frequency of 33 MHz. The IF stages in any superhet receiver are where the main signal voltage amplification takes place.','30F5 7ED7 PF818',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('Z749','Z749','RF pentode','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The Z749 is a screened amplifier pentode, the GEC name was used as the professional brand of M-OV. The Z749 is directly equivalent to the EF812 and closely related to the EF80. TV and radar receivers would require wide bandwidth RF amplification.','6EL7 6F23 EF812',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('Z759','Z759','RF pentode','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The Z759 is an RF pentode with a high mutual conductance designed for video or other wideband RF amplification.','CV5060',NULL,NULL,'inferred',NULL);
